from pathlib import Path
import os
os.chdir(Path(__file__).resolve().parent)

import re
with open('./plugins/movie_downloader_plugin.py', 'r', encoding='utf-8') as f: content = f.read()
new_download = '''        elif action == "download":\n            if player: player.write_log("MOVIE DOWNLOADER: Pokrecem Nemilosrdnog Watchdog agenta...")\n            need_search = False\n            try:\n                with open("last_movie_results.json", "r") as f: results = json.load(f)\n            except:\n                results = []\n            if val and val != "start" and not val.startswith("magnet:"):\n                if not results or val.lower().replace(" ", "") not in results[0].get("title", "").lower().replace(" ", "").replace(".", ""):\n                    need_search = True\n            if need_search or not results:\n                results = md.search_torrentgalaxy(val)\n                if not results: return f"Nisam nasao nijedan torrent za '{val}'."\n                with open("last_movie_results.json", "w") as f: json.dump(results, f)\n                best = results[0]\n                md.send_telegram_confirmation(val, f"Naziv: {best['title']}\nWatchdog preuzima kontrolu!")\n            \n            # Pokreni Watchdog u pozadini\n            import subprocess\n            watchdog_path = os.path.join(r"./.agents/plugins/movie_downloader", "movie_watchdog.py")\n            subprocess.Popen([sys.executable, watchdog_path], creationflags=subprocess.CREATE_NEW_CONSOLE | subprocess.DETACHED_PROCESS if hasattr(subprocess, "DETACHED_PROCESS") else 0, cwd=r".")\n            \n            return "Nemilosrdni Watchdog agent je pusten s lanca u pozadini! Prati tvoj Telegram za live izvestaje dok Ultron moze da radi nesto drugo!"\n        else:'''
content = re.sub(r'        elif action == "download":.*?        else:', new_download, content, flags=re.DOTALL)
with open('./plugins/movie_downloader_plugin.py', 'w', encoding='utf-8') as f: f.write(content)
